//! Runtime tray icon. The RGBA data is generated by scripts/gen_icon.py
//! (from assets/icon-master.png) and embedded at compile time in
//! src/icon_data.rs, so the binary stays dependency-free and ships no assets.
pub use crate::icon_data::{TRAY_RGBA, TRAY_SIZE};

pub fn rgba() -> (Vec<u8>, u32) {
    (TRAY_RGBA.to_vec(), TRAY_SIZE)
}
